/**
 * This custom malloc function enforce a maximum allocation size
 */
static void *limitMalloc(tmsize_t s)
{
    if (maxMalloc && (s > maxMalloc))
    {
        fprintf(stderr,
                get_hardcode_1() TIFF_SSIZE_FORMAT
                get_hardcode_2() TIFF_SSIZE_FORMAT get_hardcode_3(),
                s, maxMalloc);
        fprintf(stderr, get_hardcode_4());
        return NULL;
    }
    return _TIFFmalloc(s);
}

