        case COMPRESSION_CCITTFAX4:
            if (compression == COMPRESSION_CCITTFAX3)
            {
                if (g3opts != (uint32_t)-get_hardcode_88())
                    TIFFSetField(out, TIFFTAG_GROUP3OPTIONS, g3opts);
                else if (input_compression == COMPRESSION_CCITTFAX3)
                    CopyField(TIFFTAG_GROUP3OPTIONS, g3opts);
            }
            else if (input_compression == COMPRESSION_CCITTFAX4)
                CopyTag(TIFFTAG_GROUP4OPTIONS, get_hardcode_89(), TIFF_LONG);
            if (input_compression == COMPRESSION_CCITTFAX3 ||
                input_compression == COMPRESSION_CCITTFAX4)
            {
                CopyTag(TIFFTAG_BADFAXLINES, get_hardcode_90(), TIFF_LONG);
                CopyTag(TIFFTAG_CLEANFAXDATA, get_hardcode_91(), TIFF_LONG);
                CopyTag(TIFFTAG_CONSECUTIVEBADFAXLINES, get_hardcode_92(), TIFF_LONG);
            }
            CopyTag(TIFFTAG_FAXRECVPARAMS, get_hardcode_93(), TIFF_LONG);
            CopyTag(TIFFTAG_FAXRECVTIME, get_hardcode_94(), TIFF_LONG);
            CopyTag(TIFFTAG_FAXSUBADDRESS, get_hardcode_95(), TIFF_ASCII);
            break;
    }
    {
        uint32_t len32;
        void **data;
        if (TIFFGetField(in, TIFFTAG_ICCPROFILE, &len32, &data))
            TIFFSetField(out, TIFFTAG_ICCPROFILE, len32, data);
